#include <stdio.h>                      /* a header: declarations for printf */

int square(int n) { return n * n; }     /* a function: type, name, parameters */

int main(void) {                        /* execution starts here */
    int total = 0;                      /* variables have declared types */
    for (int n = 1; n <= 10; n += 2)    /* the odd numbers 1, 3, 5, 7, 9 */
        total += square(n);
    printf("%d\n", total);              /* prints 165 */
    return 0;
}

#include <cstdio>
#include <vector>

struct Account {                         // a class: data plus the code that works on it
    std::vector<int> cents;              // a growable array that frees its own memory
    void deposit(int c) { cents.push_back(c); }
    int total() const { int t = 0; for (int c : cents) t += c; return t; }
};

int main() {
    Account a;
    a.deposit(500);
    a.deposit(250);
    std::printf("%d\n", a.total());      // 750; no malloc or free anywhere
}                                        // a and its vector are destroyed here, automatically

import java.util.stream.IntStream;

public class SumSquares {
    public static void main(String[] args) {
        int total = IntStream.rangeClosed(1, 10)
                .filter(n -> n % 2 == 1)      // a lambda (Java 8, 2014)
                .map(n -> n * n)
                .sum();
        System.out.println(total);            // 165
    }
}

