#include <stdio.h>

void swap(int *a, int *b) {        /* a and b hold addresses of ints */
    int t = *a;                    /* *a means the int that a points at */
    *a = *b;
    *b = t;
}

int main(void) {
    int x = 1, y = 2;
    swap(&x, &y);                  /* &x is the address of x */
    printf("%d %d\n", x, y);       /* prints 2 1 */
    return 0;
}

class Shape:
    def describe(self):                      # written once, for every kind of shape
        return f"{self.name()} with area {self.area()}"

class Rect(Shape):                           # inheritance: a Rect is a Shape
    def __init__(self, w, h): self.w, self.h = w, h    # data...
    def name(self): return "rectangle"
    def area(self): return self.w * self.h             # ...and the code that uses it

class Square(Rect):
    def __init__(self, side): super().__init__(side, side)
    def name(self): return "square"          # overrides Rect.name

for s in [Rect(2, 3), Square(4)]:
    print(s.describe())     # rectangle with area 6, then square with area 16

