-- After: the relational model. Tables and keys, then a query that says what is wanted
CREATE TABLE department (code INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE employee (id INTEGER PRIMARY KEY, name TEXT, department_code INTEGER REFERENCES department(code));
SELECT e.name FROM employee AS e JOIN department AS d ON d.code = e.department_code WHERE d.name = 'Sales';

CREATE TABLE note (id serial PRIMARY KEY, body jsonb);      -- JSON stored inside a relational table
